<?php
declare(strict_types=1);
require __DIR__.'/../includes/bootstrap.php';
require __DIR__.'/../includes/timeclock-voice-core.php';
$user=app_require_auth();$pdo=app_pdo();$org=(int)$user['organization_id'];$uid=(int)$user['id'];
if(!tv_ready($pdo))app_json_response(['ok'=>false,'message'=>'Time Clock + Voice Agent migration is not installed. Run upgrade.php.'],503);
function tc_can(array $u,string $p):bool{return app_has_permission($p,$u);}function tc_need(array $u,string $p):void{if(!tc_can($u,$p))app_json_response(['ok'=>false,'message'=>'Permission required: '.$p],403);}function tc_error(Throwable $e):never{$s=$e instanceof InvalidArgumentException?422:($e instanceof RuntimeException?403:500);app_json_response(['ok'=>false,'message'=>$e->getMessage()],$s);}
if($_SERVER['REQUEST_METHOD']==='GET'){
