  if($action==='bootstrap'){$profile=tv_voice_profile($pdo,$org,$uid,false);$snapshot=tv_self_snapshot($pdo,$org,$uid);$snapshot['currentBreak']=null;if(!empty($snapshot['clock']['id'])){$b=$pdo->prepare('SELECT id,started_at,break_type,source FROM time_clock_breaks WHERE organization_id=? AND time_clock_entry_id=? AND ended_at IS NULL ORDER BY started_at DESC LIMIT 1');$b->execute([$org,(int)$snapshot['clock']['id']]);$snapshot['currentBreak']=$b->fetch()?:null;}app_json_response(['ok'=>true,'date'=>$date,'self'=>$snapshot,'entries'=>tv_clock_rows($pdo,$org,$date,$manager?null:$uid),'summary'=>$manager?tv_daily_summary($pdo,$org,$date):null,'noShows'=>tc_can($user,'attendance.view')?tv_no_shows($pdo,$org):[],'voiceProfile'=>$profile,'permissions'=>['self'=>$self,'view'=>tc_can($user,'timeclock.view'),'manage'=>tc_can($user,'timeclock.manage'),'attendance'=>tc_can($user,'attendance.view'),'voiceSelf'=>tc_can($user,'voice.self'),'voiceManage'=>tc_can($user,'voice.manage'),'voiceAgent'=>tc_can($user,'voice.agent'),'proactive'=>tc_can($user,'agent.proactive')]]);}
  if($action==='entries'){app_json_response(['ok'=>true,'entries'=>tv_clock_rows($pdo,$org,$date,$manager?null:$uid)]);}
  if($action==='summary'){tc_need($user,'attendance.view');app_json_response(['ok'=>true,'summary'=>tv_daily_summary($pdo,$org,$date),'noShows'=>tv_no_shows($pdo,$org)]);}
  app_json_response(['ok'=>false,'message'=>'Unsupported time clock action.'],422);
}
if($_SERVER['REQUEST_METHOD']!=='POST'){header('Allow: GET, POST');app_json_response(['ok'=>false,'message'=>'Method not allowed.'],405);} $in=app_json_input();app_verify_request_csrf($in);$action=(string)($in['action']??'');
try{
  if(in_array($action,['clock_in','clock_out','break_start','break_end'],true)){tc_need($user,'timeclock.self');$source=(string)($in['source']??'manual');if(!in_array($source,['manual','voice','agent'],true))$source='manual';if($source==='agent')$source='manual';$voice=(string)($in['voiceEventId']??'');$note=(string)($in['note']??'');if($action==='clock_in')$row=tv_clock_in($pdo,$org,$uid,$uid,$source,$note,$voice);elseif($action==='clock_out')$row=tv_clock_out($pdo,$org,$uid,$uid,$source,$note,$voice);else$row=tv_break_action($pdo,$org,$uid,$uid,$action==='break_start'?'start':'end',$source,$voice);app_json_response(['ok'=>true,'result'=>$row,'message'=>str_replace('_',' ',ucfirst($action)).' complete.']);}
